-- small helpers ---------------------------------------------------------------------------------------------
function PTSH_No()
end

function PTSH_Now()
	local t = SystemTime()
	if t == nil then t = 0 end
	return t
end

-- player id kept in an npc param (int): reduced so that a DWORD id never turns negative
function PTSH_Me()
	local id = GetPlayerID()
	if id == nil then id = 0 end
	return mod(id, 1000000000)
end

function PTSH_Day()
	local d = nil
	if date then d = tonumber(date("%Y%m%d")) end
	if d == nil or d <= 0 then d = floor(PTSH_Now() / 86400) end
	return d
end

function PTSH_Hour()
	local h = nil
	if date then h = tonumber(date("%H")) end
	if h == nil then h = 0 end
	return h
end

function PTSH_Rand(a, b)
	if b <= a then return a end
	local r = random(a, b)
	if r == nil or r < a then r = a end
	if r > b then r = b end
	return r
end

function PTSH_Pick(t)
	return t[PTSH_Rand(1, getn(t))]
end

function PTSH_Digit(v, k)
	local p = 1
	local i = 1
	while i < k do p = p * 10 i = i + 1 end
	return mod(floor(v / p), 10)
end

function PTSH_SetDigit(v, k, d)
	local p = 1
	local i = 1
	while i < k do p = p * 10 i = i + 1 end
	return v - PTSH_Digit(v, k) * p + d * p
end

function PTSH_Note(id, title, text, act)
	if AddNote then AddNote(mod(id, 36), act, title .. ": " .. text, 0) end
end

function PTSH_Free()
	if CalcFreeItemCellCount then
		local n = CalcFreeItemCellCount()
		if n == nil then return 0 end
		return n
	end
	return 10
end

function PTSH_Count(g, d, p)
	local n = 0
	if g == 6 then n = HaveNormalItem(6, 1, d, -1) else n = HaveNormalItem(g, d, p, -1) end
	if n == nil then n = 0 end
	return n
end

function PTSH_Give(g, d, p, n)
	local k = 0
	local i = 1
	while i <= n do
		local r = 0
		if g == 6 then r = AddNormalItem(6, 1, d, 1, 0, 0) else r = AddNormalItem(g, d, p, 1, 0, 0) end
		if r and r > 0 then k = k + 1 end
		i = i + 1
	end
	return k
end

-- take n of one item from the bag (DelNormalItem only takes from the bag; HaveNormalItem also counts the
-- storage box): returns the number removed
function PTSH_Take(g, d, p, n)
	local k = 0
	while k < n do
		local r = 0
		if g == 6 then r = DelNormalItem(6, 1, d, -1) else r = DelNormalItem(g, d, p, -1) end
		if r == nil or r <= 0 then break end
		k = k + 1
	end
	return k
end

-- list = { {g, d, p, n}, ... }: all-or-nothing; gives back what was taken when something is missing
function PTSH_TakeAll(list)
	local i = 1
	while list[i] do
		local q = list[i]
		if PTSH_Count(q[1], q[2], q[3]) < q[4] then return 0 end
		i = i + 1
	end
	local got = {}
	i = 1
	while list[i] do
		local q = list[i]
		got[i] = PTSH_Take(q[1], q[2], q[3], q[4])
		if got[i] < q[4] then
			local j = 1
			while j <= i do
				local r = list[j]
				PTSH_Give(r[1], r[2], r[3], got[j])
				j = j + 1
			end
			return -1
		end
		i = i + 1
	end
	return 1
end

-- materials by tier ------------------------------------------------------------------------------------------
-- q = { type, id offset, tier from, tier to, count }
function PTSH_TierCount(q)
	local n = 0
	local t = q[3]
	while t <= q[4] do
		local ids = PTSH_MAT[q[1]][t]
		local j = 1
		while ids[j] do
			n = n + PTSH_Count(3, ids[j] + q[2], 0)
			j = j + 1
		end
		t = t + 1
	end
	return n
end

function PTSH_TierTake(q)
	local want = q[5]
	if PTSH_TierCount(q) < want then return 0 end
	local taken = {}
	local k = 0
	local t = q[3]
	while t <= q[4] and k < want do
		local ids = PTSH_MAT[q[1]][t]
		local j = 1
		while ids[j] and k < want do
			local id = ids[j] + q[2]
			local c = PTSH_Count(3, id, 0)
			if c > want - k then c = want - k end
			if c > 0 then
				local g = PTSH_Take(3, id, 0, c)
				taken[id] = (taken[id] or 0) + g
				k = k + g
			end
			j = j + 1
		end
		t = t + 1
	end
	if k < want then
		PTSH_GiveBack(taken)
		return -1
	end
	PTSH_LAST_TAKEN = taken
	return 1
end

function PTSH_GiveBack(taken)
	if taken == nil then return end
	for id, g in taken do PTSH_Give(3, id, 0, g) end
end

-- life skills --------------------------------------------------------------------------------------------
function PTSH_SkillExp(k)
	return GetTask(PTSH_T_SKILL0 + k)
end

function PTSH_SkillCap(k)
	if PTSH_Digit(GetTask(PTSH_T_TONSU), k) == 1 then return 10 end
	return 9
end

function PTSH_SkillLevel(k)
	local e = PTSH_SkillExp(k)
	local cap = PTSH_SkillCap(k)
	local lv = 1
	while lv < cap and e >= PTSH_EXP_TBL[lv + 1] do lv = lv + 1 end
	return lv
end

function PTSH_AddSkillExp(k, n)
	local before = PTSH_SkillLevel(k)
	local e = PTSH_SkillExp(k) + n
	if e > 99999 then e = 99999 end
	SetTask(PTSH_T_SKILL0 + k, e)
	local after = PTSH_SkillLevel(k)
	if after > before then
		Msg2Player("K\252 n\168ng <color=yellow>" .. PTSH_SKILL_NAME[k] .. "<color> l\170n c\202p " .. after .. ".")
	end
	return after
end

function PTSH_HasBook(id)
	if HaveMagic == nil then return 0 end
	local l = HaveMagic(id)
	if l == nil or l <= 0 then return 0 end
	return 1
end

function PTSH_Teach(id)
	if PTSH_HasBook(id) == 1 then return 1 end
	if GetCash() < PTSH_TEACH_FEE or Pay(PTSH_TEACH_FEE) ~= 1 then return -2 end
	local r = AddMagic(id, 1)
	if PTSH_HasBook(id) == 1 then return 1 end
	if DelMagic then DelMagic(id) end
	Earn(PTSH_TEACH_FEE)
	return -1
end

function PTSH_InCity()
	local w = GetWorldPos()
	if w == 1001 or w == 1002 or w == 1003 or w == 1004 or w == 1020 or w == 1021 or w == 1052 then return 1 end
	return 0
end

-- Le Quan event hours: 12:00-13:59 and 19:00-22:59 (server clock)
function PTLQ_Open()
	local h = PTSH_Hour()
	if h == 12 or h == 13 then return 1 end
	if h >= 19 and h <= 22 then return 1 end
	return 0
end

