function PTLT_Stage(k)
	if k == nil or k < 1 or k > 8 then return 0 end
	return PTSH_Digit(GetTask(PTLT_T_OWN), k)
end

function PTLT_SetStage(k, s)
	SetTask(PTLT_T_OWN, PTSH_SetDigit(GetTask(PTLT_T_OWN), k, s))
end

function PTLT_OwnedCount()
	local n = 0
	local k = 1
	while k <= 8 do
		if PTLT_Stage(k) > 0 then n = n + 1 end
		k = k + 1
	end
	return n
end

function PTLT_Need(lv)
	return 10 + lv * 2
end

-- level from exp; capped at stage * 10
function PTLT_Level(k)
	local e = GetTask(PTLT_T_EXP0 + k)
	local cap = PTLT_Stage(k) * 10
	local lv = 1
	while lv < cap and e >= PTLT_Need(lv) do
		e = e - PTLT_Need(lv)
		lv = lv + 1
	end
	return lv
end

function PTLT_ExpFor(lv)
	local e = 0
	local i = 1
	while i < lv do e = e + PTLT_Need(i) i = i + 1 end
	return e
end

-- add exp to pet k, never past the stage cap: returns the exp really added
function PTLT_AddExp(k, n)
	local s = PTLT_Stage(k)
	if s <= 0 then return 0 end
	local maxe = PTLT_ExpFor(s * 10)
	local e = GetTask(PTLT_T_EXP0 + k)
	if e >= maxe then return 0 end
	local before = PTLT_Level(k)
	if e + n > maxe then n = maxe - e end
	SetTask(PTLT_T_EXP0 + k, e + n)
	local after = PTLT_Level(k)
	if after > before then
		Msg2Player("Linh th\243 <color=yellow>" .. PTLT_PET[k][1] .. "<color> l\170n c\202p " .. after .. ".")
		if after >= s * 10 and s < 4 then
			Msg2Player("Linh th\243 \174\183 \174\185t gi\237i h\185n c\202p " .. after .. ", h\183y t\215m Linh Th\243 S\248 (T\169y K\250/Tri\210u Ca) \174\211 ti\213n h\227a.")
		end
	end
	return n
end

function PTLT_Tpl(k)
	local s = PTLT_Stage(k)
	if s < 1 then s = 1 end
	return PTLT_PET[k][1 + s]
end

function PTLT_Label(k)
	return PTLT_PET[k][1] .. " - " .. PTLT_STAGE_NAME[k][PTLT_Stage(k)] .. " c\202p " .. PTLT_Level(k)
end

-- the summoned pet npc if it is still ours, else 0
function PTLT_Owned()
	local idx = GetTask(PTLT_T_NPC)
	if idx == nil or idx <= 0 then return 0 end
	if GetNpcSettingIdx(idx) ~= GetTask(PTLT_T_TPL) then return 0 end
	if GetNpcOwner(idx) ~= GetName() then return 0 end
	return idx
end

function PTLT_Dismiss(keep)
	local idx = PTLT_Owned()
	if idx > 0 then DelNpc(idx) end
	if keep == 1 then SetTask(PTLT_T_NPC, -1) else SetTask(PTLT_T_NPC, 0) end
	SetTask(PTLT_T_TPL, 0)
	return idx
end

-- pet behaviour (2026-10-03 cppbatch), decimal digit 9 of task PTLT_T_OWN (digits 1..8 are the pets):
--   0 = companion (default): AiMode 13 when the server has SetNpcAiMode (CoreServer cppbatch build), it follows
--       and never fights. Older binaries have no SetNpcAiMode: the pet keeps AiMode 11 without a skill (it runs
--       to the monsters of its owner but deals no damage), exactly as before.
--   1 = combat: AiMode 11 (AddTotemNpc default, works on every binary) + basic melee skill 63 in slots 1..4, like
--       the Di Nhan templates (359...). Damage and life are copied from the owner by SetNpcOwner.
-- VNG attribute pets (common\shu xing ling chong) have no combat skill; combat mode is a Phong Than option.
PTLT_MODE_DIGIT = 9
PTLT_ATK_SKILL = 63
PTLT_ATK_LEVEL = 1

function PTLT_Mode()
	return PTSH_Digit(GetTask(PTLT_T_OWN), PTLT_MODE_DIGIT)
end

function PTLT_SetMode(m)
	SetTask(PTLT_T_OWN, PTSH_SetDigit(GetTask(PTLT_T_OWN), PTLT_MODE_DIGIT, m))
end

-- 1 when the running server can make a real companion (capability check, old binaries return nil)
function PTLT_HasCompanionAI()
	if SetNpcAiMode then return 1 end
	return nil
end

function PTLT_ApplyMode(idx)
	if PTLT_Mode() == 1 then
		local i = 1
		while i <= 4 do
			SetNpcSkill(idx, PTLT_ATK_SKILL, PTLT_ATK_LEVEL, i)
			i = i + 1
		end
		if SetNpcAiMode then SetNpcAiMode(idx, 11) end
	else
		if SetNpcAiMode then SetNpcAiMode(idx, 13) end
	end
end

-- summon the active pet next to the player: AddTotemNpc = owner + AiMode 11 (follows, removed by the engine when
-- the owner dies or changes map). The VNG pet templates are Kind 10, outside the engine's kind x camp relation
-- table (kind_num = 6): SetNpcKind(.., 0) before the first sync makes it an ordinary NPC of the owner's camp
-- (the cppbatch CoreServer build also clamps Kind in KNpcTemplate; keeping the call is harmless).
-- PTLT_ApplyMode then picks companion (AiMode 13) or combat (AiMode 11 + skill 63). Di Nhan summons (tasks
-- 1941/1942, m_nPetIdx) are not touched.
function PTLT_Summon()
	local k = GetTask(PTLT_T_ACT)
	if PTLT_Stage(k) <= 0 then return 0 end
	PTLT_Dismiss(0)
	local w = GetWorldPos()
	local sw = SubWorldID2Idx(w)
	if sw == nil or sw < 0 then return 0 end
	local pn = GetPlayerNpcIdx()
	local pw, x, y = GetNpcPos(pn)
	local tpl = PTLT_Tpl(k)
	local idx = AddTotemNpc(tpl, GetLevel(), sw, x * 32 + 48, y * 32 + 48)
	if idx == nil or idx <= 0 then return 0 end
	SetNpcKind(idx, 0)
	SetNpcCurCamp(idx, GetCurCamp())
	SetNpcOwner(idx, GetName(), 0)
	PTLT_ApplyMode(idx)
	SetNpcName(idx, PTLT_PET[k][1] .. " [" .. PTLT_Level(k) .. "]")
	SetTask(PTLT_T_NPC, idx)
	SetTask(PTLT_T_TPL, tpl)
	return idx
end

