-- day * 10 + count, reset when the day changes
function PTLQ_DayCount(task)
	local v = GetTask(task)
	if floor(v / 10) ~= PTSH_Day() then return 0 end
	return mod(v, 10)
end

function PTLQ_DayInc(task)
	SetTask(task, PTSH_Day() * 10 + PTLQ_DayCount(task) + 1)
end

function PTLQ_TaskId(normal, noon)
	if PTSH_Hour() < 18 then return noon end
	return normal
end

function PTLQ_ChalRunning()
	local s = GetTask(PTLQ_T_CHAL)
	if s <= 0 then return 0 end
	local now = PTSH_Now()
	if now - s > PTLQ_CHAL_SEC or now < s then
		SetTask(PTLQ_T_CHAL, 0)
		return 0
	end
	return s
end

-- event reward: random pet egg with chance pct (percent)
function PTLQ_EggChance(pct)
	if PTSH_Rand(1, 100) > pct then return 0 end
	local k = PTSH_Rand(1, 8)
	if PTSH_Give(6, PTLT_I_EGG0 + k, 0, 1) > 0 then
		Msg2Player("May m\190n! Nh\203n \174\173\238c <color=yellow>Tr\248ng Linh Th\243 " .. PTLT_PET[k][1] .. "<color>.")
		if AddGlobalNews then AddGlobalNews(GetName() .. " tham gia l\212 h\233i nh\203n \174\173\238c Tr\248ng Linh Th\243 " .. PTLT_PET[k][1] .. "!") end
		return k
	end
	return 0
end
-- pet actions shared by Linh Thu Lenh / Linh Thu Don / eggs / the minute tick -----------------------------------
-- feed one Linh Thu Don (already taken by the caller): returns the exp added (0 = at the stage cap)
function PTLT_Feed()
	local k = GetTask(PTLT_T_ACT)
	if PTLT_Stage(k) <= 0 then return -1 end
	local n = PTLT_AddExp(k, PTLT_FOOD_EXP)
	local idx = PTLT_Owned()
	if idx > 0 then SetNpcName(idx, PTLT_PET[k][1] .. " [" .. PTLT_Level(k) .. "]") end
	return n
end

-- egg of pet k (item index it): adopt the pet, keep the egg when the pet is already owned
function PTLT_UseEgg(it, k)
	if PTLT_Stage(k) > 0 then
		Say("Ng\173\172i \174\183 c\227 linh th\243 <color=yellow>" .. PTLT_PET[k][1] .. "<color> r\229i. C\227 th\211 gi\247 tr\248ng \174\211 t\198ng ng\173\234i kh\184c.", 1, "\167\227ng/PTSH_No")
		return 0
	end
	PTLT_SetStage(k, 1)
	SetTask(PTLT_T_EXP0 + k, 0)
	if PTLT_Stage(GetTask(PTLT_T_ACT)) <= 0 then SetTask(PTLT_T_ACT, k) end
	RemoveItem(it, 1, 0)
	if PTSH_Count(6, PTLT_I_LENH, 0) <= 0 then PTSH_Give(6, PTLT_I_LENH, 0, 1) end
	PTSH_Note(PTLT_PET[k][6], PTLT_STAGE_NAME[k][1], "Linh th\243 " .. PTLT_PET[k][1] .. " \174\183 n\235. Tri\214u h\229i b\187ng Linh Th\243 L\214nh, cho \174i theo khi chi\213n \174\202u \174\211 l\170n c\202p.", 1)
	Say("Tr\248ng n\235 ra <color=yellow>" .. PTLT_PET[k][1] .. "<color>! D\239ng <color=yellow>Linh Th\243 L\214nh<color> \174\211 tri\214u h\229i. Linh th\243 \174i theo khi ng\173\172i chi\213n \174\202u s\207 l\170n c\202p v\181 gi\243p ng\173\172i th\170m kinh nghi\214m.", 1, "\167\227ng/PTSH_No")
	return 1
end

-- minute tick for the current PlayerIndex (called by script\phongthan\ext\sinhhoat.lua)
if PTLT_MIN == nil then PTLT_MIN = {} end
function PTLT_TickPlayer()
	local want = GetTask(PTLT_T_NPC)
	if want == nil or want == 0 then return 0 end
	local k = GetTask(PTLT_T_ACT)
	if PTLT_Stage(k) <= 0 then
		SetTask(PTLT_T_NPC, 0)
		return 0
	end
	local idx = PTLT_Owned()
	if idx <= 0 then
		-- the engine removed the pet (owner died / changed map): bring it back while the owner is alive
		if GetLife and GetLife() <= 0 then return 0 end
		SetTask(PTLT_T_NPC, -1)
		if PTLT_Summon() > 0 then return 2 end
		return 0
	end
	if GetFightState() ~= 1 then return 1 end
	local s = PTLT_Stage(k)
	local before = PTLT_Level(k)
	PTLT_AddExp(k, 1)
	if PTLT_Level(k) ~= before then SetNpcName(idx, PTLT_PET[k][1] .. " [" .. PTLT_Level(k) .. "]") end
	AddOwnExp(GetLevel() * 10 * s)
	local nm = GetName()
	local c = (PTLT_MIN[nm] or 0) + 1
	PTLT_MIN[nm] = c
	if s >= 2 and mod(c, 10) == 0 and PTSH_Free() > 0 then
		local typ = PTSH_Rand(1, 3)
		local t = PTSH_Rand(1, s * 2)
		local id = PTSH_Pick(PTSH_MAT[typ][t])
		if PTSH_Give(3, id, 0, 1) > 0 then
			Msg2Player("Linh th\243 " .. PTLT_PET[k][1] .. " tha v\210 cho ng\173\172i m\233t nguy\170n li\214u.")
		end
	end
	return 3
end